'use strict';
window.initLiveDirectory=function(root){
 const section=root.querySelector('.live-discovery');if(!section)return;
 const platform=root.dataset.platform,brand=platform==='x'?'X':'Twitch',list=section.querySelector('.live-channel-list'),search=section.querySelector('.live-search'),category=section.querySelector('.live-category'),only=section.querySelector('.live-only'),status=section.querySelector('.directory-status'),more=section.querySelector('.directory-more'),refresh=section.querySelector('.directory-refresh'),monitorForm=section.querySelector('.monitor-form'),monitorInput=section.querySelector('.monitor-name'),monitorList=section.querySelector('.monitor-list'),announcement=section.querySelector('.live-announcement'),banner=root.querySelector('.live-banner'),track=banner.querySelector('.live-track'),pause=banner.querySelector('.ticker-pause');
 const key='iptv-'+platform+'-monitors',limit=platform==='x'?4:12,pattern=platform==='x'?/^[a-zA-Z0-9_]{1,15}$/:/^[a-zA-Z0-9_]{1,25}$/;
 let monitors=[];try{const stored=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(stored))monitors=stored.filter(x=>typeof x==='string'&&pattern.test(x)).slice(0,limit);}catch{}
 let snapshot=null,channels=[],count=12,timer,request,disposed=false,generation=0,stale=false,highlighted=[];
 function node(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text)n.textContent=text;return n;}
 function watch(item){if(!item.url)return;const input=root.querySelector('#social-url');input.value=item.url;root.querySelector('#social-form').requestSubmit();root.querySelector('#social-form').scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
 function render(){const needle=search.value.trim().toLowerCase(),selected=channels.filter(c=>(category.value==='all'||c.category===category.value)&&(!only.checked||c.state==='live')&&[c.name,c.username,c.title,c.category].join(' ').toLowerCase().includes(needle));const focused=list.contains(document.activeElement)?document.activeElement.dataset.watch:null;list.replaceChildren();
 for(const item of selected.slice(0,count)){const article=node('article','live-channel'),preview=node('div','channel-preview'),info=node('div','discovery-channel-info'),header=node('div','discovery-channel-header');
  const imageURL=item.poster||item.avatar;if(imageURL){const image=node('img');image.src=imageURL;image.alt='';image.loading='lazy';image.referrerPolicy='no-referrer';image.addEventListener('error',()=>image.remove());preview.append(image);}else preview.innerHTML=heroIcon('play');
  preview.append(node('span','discovery-state',item.state==='live'?(stale?'Last seen live':'Live'):item.state==='replay'?'Replay':item.state==='video'?'Video':item.state==='offline'?(platform==='x'?'No public live found':'Offline'):'Status unavailable'));
  header.append(node('strong','',item.name),node('span','',item.category));info.append(header,node('p','discovery-handle','@'+item.username),node('p','discovery-title',item.title||'No public video available.'));
  if(Number.isFinite(item.viewers))info.append(node('p','discovery-viewers',new Intl.NumberFormat().format(item.viewers)+' viewers'));
  const button=node('button');button.type='button';button.dataset.watch=item.id;setControlLabel(button,item.state==='live'?(stale?'Check stream':'Watch live'):item.url?'Watch video':'Currently unavailable',item.state==='live'?'play':'arrow-top-right-on-square');button.disabled=!item.url;button.setAttribute('aria-label',(item.state==='live'?'Watch live: ':'Watch video: ')+item.name);button.addEventListener('click',()=>watch(item));info.append(button);article.append(preview,info);list.append(article);
 }
 if(!selected.length)list.append(node('p','directory-empty',snapshot?'No channels match these filters. Try another category or turn off Live only.':'Live channels will appear here after the directory loads.'));
 more.hidden=selected.length<=count;section.querySelector('.directory-count').textContent=selected.length+' '+(selected.length===1?'channel':'channels');
 if(focused)[...list.querySelectorAll('[data-watch]')].find(b=>b.dataset.watch===focused)?.focus({preventScroll:true});
 }
 function ticker(){const live=channels.filter(c=>c.state==='live'&&c.url).sort((a,b)=>Number(highlighted.includes(b.id))-Number(highlighted.includes(a.id)));track.replaceChildren();banner.querySelector('.ticker-label').textContent=(stale?'Last checked':'Live now')+(live.length?' · '+live.length:'');if(!live.length){track.append(node('span','ticker-empty',snapshot?.partial?'Live status is unavailable for some monitored accounts.':'No monitored channels are live right now.'));pause.hidden=true;return;}
 pause.hidden=false;const copy=node('div','ticker-copy');for(const item of live.slice(0,20)){const button=node('button','ticker-item',item.name+(stale?' was live at last check — ':' is live — ')+item.title.slice(0,90));button.type='button';button.addEventListener('click',()=>watch(item));copy.append(button);}track.append(copy);const duplicate=copy.cloneNode(true);duplicate.setAttribute('aria-hidden','true');[...duplicate.querySelectorAll('button')].forEach((b,i)=>{b.tabIndex=-1;b.addEventListener('click',()=>watch(live[i]));});track.append(duplicate);track.style.setProperty('--ticker-duration',Math.max(35,Math.min(120,live.length*8))+'s');
 }
 function update(data){const previous=new Map((snapshot?.channels||[]).map(c=>[c.id,c]));const newlyLive=snapshot?data.channels.filter(c=>c.state==='live'&&previous.has(c.id)&&previous.get(c.id).state!=='live'&&previous.get(c.id).state!=='unknown'):[];
 highlighted=newlyLive.map(c=>c.id);stale=false;channels=data.channels;snapshot=data;const current=category.value;category.replaceChildren(new Option('All categories','all'));for(const c of data.categories)category.append(new Option(c,c));category.value=data.categories.includes(current)?current:'all';
 announcement.textContent=newlyLive.map(c=>c.name+' is now live.').join(' ');ticker();render();const time=new Date(data.checkedAt);status.textContent=(platform==='twitch'?'Popular live streams and monitored channels. ':'Featured accounts and their public videos. ')+(data.partial?'Some account statuses could not be checked. ':'')+'Updated '+time.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})+'. Checks every minute while this page is open.';
 }
 function schedule(){clearTimeout(timer);if(!disposed&&!document.hidden)timer=setTimeout(load,60000);}
 async function load(){if(disposed||document.hidden||request)return;clearTimeout(timer);const current=++generation;const controller=new AbortController();request=controller;const timeout=setTimeout(()=>controller.abort(),55000);refresh.disabled=true;setControlLabel(refresh,'Checking…','arrow-path');section.setAttribute('aria-busy','true');
  try{const params=new URLSearchParams({platform});if(monitors.length)params.set('channels',monitors.join(','));const response=await fetch('/api/live-directory?'+params,{signal:controller.signal});const result=await response.json();if(!response.ok)throw Error(result.error||'The live directory is unavailable.');if(!disposed&&current===generation)update(result);}
  catch(e){if(!disposed&&current===generation){announcement.textContent='';if(snapshot){stale=true;ticker();render();}else{banner.querySelector('.ticker-label').textContent='Live status unavailable';track.replaceChildren(node('span','ticker-empty','Use Refresh to check live channels again.'));pause.hidden=true;}status.textContent=(snapshot?'Showing the last checked channels. ':'')+(e.name==='AbortError'?'The live check took too long.':e.message)+' Use Refresh to try again.';}}
  finally{clearTimeout(timeout);if(current===generation){request=null;refresh.disabled=false;setControlLabel(refresh,'Refresh','arrow-path');refresh.classList.remove('is-loading');section.setAttribute('aria-busy','false');schedule();}}
 }
 function saved(){try{localStorage.setItem(key,JSON.stringify(monitors));}catch{}renderMonitors();generation++;request?.abort();request=null;load();}
 function renderMonitors(){monitorList.replaceChildren();for(const name of monitors){const button=node('button','monitor-remove','@'+name+' · Remove');button.type='button';button.setAttribute('aria-label','Stop monitoring '+name);button.addEventListener('click',()=>{monitors=monitors.filter(n=>n!==name);saved();});monitorList.append(button);}}
 monitorForm.addEventListener('submit',event=>{event.preventDefault();const name=monitorInput.value.trim().replace(/^@/,'').toLowerCase();if(!pattern.test(name)){status.textContent='Enter a valid '+brand+' username.';return;}if(monitors.includes(name)){status.textContent='You are already monitoring @'+name+'.';return;}if(monitors.length>=limit){status.textContent='You can monitor up to '+limit+' additional accounts. Remove one to add another.';return;}monitors.push(name);monitorInput.value='';saved();});
 for(const input of [search,category,only])input.addEventListener(input===search?'input':'change',()=>{count=12;render();});more.addEventListener('click',()=>{count+=12;render();});refresh.addEventListener('click',load);pause.addEventListener('click',()=>{const paused=banner.classList.toggle('is-paused');pause.setAttribute('aria-pressed',String(paused));setControlLabel(pause,paused?'Resume notices':'Pause notices',paused?'play':'stop');});
 function visibility(){clearTimeout(timer);generation++;request?.abort();request=null;if(!document.hidden)load();}document.addEventListener('visibilitychange',visibility);window.addEventListener('pagehide',()=>{disposed=true;generation++;clearTimeout(timer);request?.abort();document.removeEventListener('visibilitychange',visibility);},{once:true});
 setControlLabel(pause,'Pause notices','stop');setControlLabel(refresh,'Refresh','arrow-path');refresh.classList.remove('is-loading');renderMonitors();render();load();
};
